    starter: {"python":"n = int(input())\nnums = list(map(int, input().split()))\nx = int(input())\n\nfound = []\n# Your code here: put every position (starting from 1) where nums has x into found\n\nif len(found) == 0:\n    print(-1)\nelse:\n    print(\" \".join(map(str, found)))\n","javascript":"const data = require('fs').readFileSync(0, 'utf8').split(/\\s+/).filter(s => s.length > 0);\nconst n = parseInt(data[0]);\nconst nums = [];\nfor (let i = 1; i <= n; i++) nums.push(parseInt(data[i]));\nconst x = parseInt(data[n + 1]);\n\nconst found = [];\n// Your code here: put every position (starting from 1) where nums has x into found\n\nif (found.length === 0) {\n  console.log(-1);\n} else {\n  console.log(found.join(\" \"));\n}\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int a[1000];\n    for (int i = 0; i < n; i++) cin >> a[i];\n    int x;\n    cin >> x;\n\n    int count = 0;\n    // Your code here: print each position (starting from 1) where a[i] == x\n    // and increase count each time you print one\n\n    if (count == 0) cout << -1;\n    cout << endl;\n    return 0;\n}\n","c":"#include <stdio.h>\n\nint main() {\n    int n, i, x, count = 0;\n    int a[1000];\n    scanf(\"%d\", &n);\n    for (i = 0; i < n; i++) scanf(\"%d\", &a[i]);\n    scanf(\"%d\", &x);\n\n    /* Your code here: print each position (starting from 1) where a[i] == x\n       and increase count each time you print one */\n\n    if (count == 0) printf(\"-1\");\n    printf(\"\\n\");\n    return 0;\n}\n","java":"import java.util.Scanner;\n\nclass Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextInt();\n        int x = sc.nextInt();\n\n        int count = 0;\n        // Your code here: print each position (starting from 1) where a[i] == x\n        // and increase count each time you print one\n\n        if (count == 0) System.out.print(-1);\n        System.out.println();\n    }\n}\n"},
