    starter: {"python":"n = int(input())\nnums = list(map(int, input().split()))\n\nbig = nums[0]\n# Your code here: find the largest value, then the largest value that is not equal to it\nsecond = nums[0]\n\nprint(second)\n","javascript":"const data = require('fs').readFileSync(0, 'utf8').split(/\\s+/).filter(s => s.length > 0);\nconst n = parseInt(data[0]);\nconst nums = [];\nfor (let i = 1; i <= n; i++) nums.push(parseInt(data[i]));\n\nlet big = nums[0];\n// Your code here: find the largest value, then the largest value that is not equal to it\nlet second = nums[0];\n\nconsole.log(second);\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int a[1000];\n    for (int i = 0; i < n; i++) cin >> a[i];\n\n    int big = a[0];\n    int second = a[0];\n    // Your code here: find the largest value, then the largest value that is not equal to it\n\n    cout << second << endl;\n    return 0;\n}\n","c":"#include <stdio.h>\n\nint main() {\n    int n, i, big, second;\n    int a[1000];\n    scanf(\"%d\", &n);\n    for (i = 0; i < n; i++) scanf(\"%d\", &a[i]);\n\n    big = a[0];\n    second = a[0];\n    /* Your code here: find the largest value, then the largest value that is not equal to it */\n\n    printf(\"%d\\n\", second);\n    return 0;\n}\n","java":"import java.util.Scanner;\n\nclass Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextInt();\n\n        int big = a[0];\n        int second = a[0];\n        // Your code here: find the largest value, then the largest value that is not equal to it\n\n        System.out.println(second);\n    }\n}\n"},
