    starter: {"python":"n = int(input())\nnums = list(map(int, input().split()))\n\nseen = []\n# Your code here: add a number to seen only if it is not already there\n\nprint(\" \".join(map(str, seen)))\n","javascript":"const data = require('fs').readFileSync(0, 'utf8').split(/\\s+/).filter(s => s.length > 0);\nconst n = parseInt(data[0]);\nconst nums = [];\nfor (let i = 1; i <= n; i++) nums.push(parseInt(data[i]));\n\nconst seen = [];\n// Your code here: add a number to seen only if it is not already there\n\nconsole.log(seen.join(\" \"));\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int a[1000];\n    for (int i = 0; i < n; i++) cin >> a[i];\n\n    // Your code here: print a[i] only if the same value did not appear before position i\n    for (int i = 0; i < n; i++) {\n        cout << a[i] << \" \";\n    }\n\n    cout << endl;\n    return 0;\n}\n","c":"#include <stdio.h>\n\nint main() {\n    int n, i;\n    int a[1000];\n    scanf(\"%d\", &n);\n    for (i = 0; i < n; i++) scanf(\"%d\", &a[i]);\n\n    /* Your code here: print a[i] only if the same value did not appear before position i */\n    for (i = 0; i < n; i++) {\n        printf(\"%d \", a[i]);\n    }\n\n    printf(\"\\n\");\n    return 0;\n}\n","java":"import java.util.Scanner;\n\nclass Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextInt();\n\n        // Your code here: print a[i] only if the same value did not appear before position i\n        for (int i = 0; i < n; i++) {\n            System.out.print(a[i] + \" \");\n        }\n\n        System.out.println();\n    }\n}\n"},
