    tests: [{"input":"8\n-2 1 -3 4 -1 2 1 -5","output":"6"},{"input":"1\n-7","output":"-7"},{"input":"5\n-3 -1 -4 -2 -5","output":"-1"},{"input":"4\n1 2 3 4","output":"10"},{"input":"6\n2 -1 2 -1 2 -1","output":"4"}],
    starter: {"python":"n = int(input())\nnums = list(map(int, input().split()))\n\nbest = nums[0]\ncur = nums[0]\n# Your code here: go through nums[1] onwards and update cur and best\n\nprint(best)\n","javascript":"const data = require('fs').readFileSync(0, 'utf8').split(/\\s+/).filter(s => s.length > 0);\nconst n = parseInt(data[0]);\nconst nums = [];\nfor (let i = 1; i <= n; i++) nums.push(parseInt(data[i]));\n\nlet best = nums[0];\nlet cur = nums[0];\n// Your code here: go through nums[1] onwards and update cur and best\n\nconsole.log(best);\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int a[1000];\n    for (int i = 0; i < n; i++) cin >> a[i];\n\n    int best = a[0], cur = a[0];\n    // Your code here: go through a[1] onwards and update cur and best\n\n    cout << best << endl;\n    return 0;\n}\n","c":"#include <stdio.h>\n\nint main() {\n    int n, i, best, cur;\n    int a[1000];\n    scanf(\"%d\", &n);\n    for (i = 0; i < n; i++) scanf(\"%d\", &a[i]);\n\n    best = a[0];\n    cur = a[0];\n    /* Your code here: go through a[1] onwards and update cur and best */\n\n    printf(\"%d\\n\", best);\n    return 0;\n}\n","java":"import java.util.Scanner;\n\nclass Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextInt();\n\n        int best = a[0];\n        int cur = a[0];\n        // Your code here: go through a[1] onwards and update cur and best\n\n        System.out.println(best);\n    }\n}\n"},
    solution: "n = int(input())\nnums = list(map(int, input().split()))\nbest = nums[0]\ncur = nums[0]\nfor i in range(1, n):\n    if cur + nums[i] > nums[i]:\n        cur = cur + nums[i]\n    else:\n        cur = nums[i]\n    if cur > best:\n        best = cur\nprint(best)\n",
